const list = [];

for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const charIndex = char.charCodeAt(0) - 97;
    const node = new Node(char, i, n);

    if (letters[charIndex]) {
        node.isSame = true;
    } else {
        letters[charIndex] = true;
    }

    list.push(node);
}

for (let i = 0; i < list.length; i++) {
    const ai = list[i];

    for (let j = i + 1; j < list.length; j++) {
        const aj = list[j];
        ai.addNext(aj.char.charCodeAt(0) - 97, aj);
    }
}

for (const node of list) {
    find(node);
}

const totalCountArray = new Array(n).fill(0n);

for (let i = 0; i < n; i++) {
    for (const node of list) {
        if (!node.isSame) {
            totalCountArray[i] += node.countArray[i];
        }
    }
}

let totalCost = 0n;
let selectCount = 0n;

for (let i = n - 1; i >= 0; i--) {
    const cost = BigInt(n - 1 - i);

    if (selectCount + totalCountArray[i] < k) {
        totalCost += cost * totalCountArray[i];
        selectCount += totalCountArray[i];
    } else {
        const over = selectCount + totalCountArray[i] - k;
        totalCost += cost * (totalCountArray[i] - over);
        selectCount += totalCountArray[i] - over;
        break;
    }
}

if (selectCount < k) {
    if (selectCount === k - 1n) {
        console.log((totalCost + BigInt(n)).toString());
    } else {
        console.log('-1');
    }
} else {
    console.log(totalCost.toString());
